<template>
  <nav class="ai-service-statuses" :aria-label="copy.title">
    <button v-for="status in statuses" :key="status.source" type="button" class="ai-service-status" :class="{'has-incident':!['none','unknown'].includes(status.indicator),'is-unknown':status.indicator==='unknown'}" :title="aiStatusTooltip(status,copy.checked)" aria-haspopup="dialog" :aria-expanded="active?.source===status.source" @click="open(status,$event)"><span aria-hidden="true">●</span>{{ status.name }} · {{ status.stale?copy.cached+' · ':'' }}{{ loading && status.indicator==='unknown'?copy.checking:states[status.indicator] || status.description }}</button>
  </nav>
  <n-modal :show="Boolean(active)" :trap-focus="true" @update:show="value=>!value && close()" @after-enter="focusClose" @after-leave="returnFocus">
    <div v-if="active" ref="dialog" class="ai-status-dialog" :style="themeStyle" role="dialog" aria-modal="true" :aria-label="active.name+' · '+copy.title" @keydown.esc.stop.prevent="close">
      <header><h2>{{ active.name }} · {{ states[active.indicator] || active.description }}</h2><button type="button" :aria-label="copy.close" @click="close">×</button></header>
      <div class="status-language" v-if="locale!=='en'"><button type="button" :aria-pressed="original" @click="original=!original">{{ original?copy.translated:copy.sourceText }}</button><span v-if="translating" role="status">{{ copy.translating }}</span><button v-else-if="failed" type="button" @click="translateDetails">{{ copy.retry }}</button></div><p class="status-checked">{{ active.stale?copy.cached+' · ':'' }}{{ copy.checked }} {{ format(active.checkedAt) }}</p>
      <ul v-if="active.affectedComponents?.length" class="status-components"><li v-for="row in active.affectedComponents" :key="row.name">{{ row.name }} · {{ states[row.status] || row.status }}</li></ul>
      <article v-for="incident in active.incidentDetails || []" :key="incident.id" class="status-incident"><h3>{{ displayText(incident.name) }}</h3><p>{{ states[incident.status] || incident.status }}<template v-if="incident.updatedAt"> · {{ format(incident.updatedAt) }}</template></p><div v-for="(update,index) in incident.updates" :key="index" class="status-update"><time v-if="update.at" :datetime="update.at">{{ format(update.at) }}</time><p>{{ displayText(update.body) }}</p></div></article>
      <p v-if="!active.incidentDetails?.length">{{ active.indicator==='none'?copy.normal:copy.noDetails }}</p>
      <footer><button v-if="active.source==='claude-status'" type="button" :aria-expanded="showSite" @click="showSite=!showSite">{{ showSite?copy.hideSite:copy.site }}</button><a :href="active.url" target="_blank" rel="noopener noreferrer">{{ copy.original }} ↗</a><span v-if="active.source==='openai-status'">{{ copy.blocked }}</span></footer>
      <iframe v-if="showSite && active.source==='claude-status'" :src="active.url" :title="active.name+' '+copy.original" sandbox="allow-scripts allow-same-origin" referrerpolicy="no-referrer" />
    </div>
  </n-modal>
</template>
<script setup>
import {computed,ref,watch} from 'vue';
import {translateReadableTitles,looksTranslatableSentence} from '@/utils/readableTitles';
import {restoreAiReadableTerms} from '@/utils/readableTranslationProtocol.mjs';
import {aiStatusTooltip} from '@/utils/aiServiceStatus.js';
const props=defineProps({statuses:{type:Array,required:true},loading:Boolean,locale:{type:String,default:'zh-CN'},themeStyle:Object});
const active=ref(null),showSite=ref(false),dialog=ref(null);let trigger,translationId=0;const original=ref(false),translations=ref({}),translating=ref(false),failed=ref(false);
const displayText=text=>!original.value && translations.value[props.locale+'|'+text] ? restoreAiReadableTerms(text,translations.value[props.locale+'|'+text]) : text;
const translateDetails=async()=>{const id=++translationId,language=props.locale,status=active.value;if(!status || language==='en')return;const texts=[...new Set((status.incidentDetails || []).flatMap(i=>[i.name,...i.updates.map(u=>u.body)]))].filter(t=>looksTranslatableSentence(t,language)).slice(0,30);translating.value=true;failed.value=false;try{const map=await translateReadableTitles(texts,language,{priority:3,allowRawFallback:true});if(id!==translationId)return;translations.value={...translations.value,...Object.fromEntries(Object.entries(map).map(([a,b])=>[language+'|'+a,b]))};failed.value=texts.some(t=>!map[t]);}catch{if(id===translationId)failed.value=true;}finally{if(id===translationId)translating.value=false;}};
watch(()=>props.locale,()=>{if(active.value)void translateDetails();});
const open=(status,event)=>{trigger=event.currentTarget;active.value=status;showSite.value=false;original.value=false;void translateDetails();};
const close=()=>{translationId++;translating.value=false;active.value=null;showSite.value=false;};
const focusClose=()=>dialog.value?.querySelector('header button')?.focus({preventScroll:true});
const returnFocus=()=>trigger?.focus({preventScroll:true});
const format=value=>value?new Date(value).toLocaleString(props.locale):'—';
const copy=computed(()=>props.locale.startsWith('zh')?{sourceText:'原文',translated:'译文',translating:'翻译中…',retry:'重试翻译',title:'服务运行状态',checked:'最近核验',cached:'上次核验',checking:'查询中',close:'关闭状态详情',normal:'官方状态页未报告当前事故。',noDetails:'未取得事故明细，可查看原站核验。',site:'在此查看官网',hideSite:'收起官网',original:'官方状态页',blocked:'OpenAI 官网禁止跨站嵌入；以上为官方接口事故明细。'}:{sourceText:'Original',translated:'Translated',translating:'Translating…',retry:'Retry translation',title:'Service status',checked:'Checked',cached:'Last check',checking:'Checking',close:'Close status details',normal:'No current incidents reported.',noDetails:'Incident details unavailable. Check the original page.',site:'View website here',hideSite:'Hide website',original:'Official status',blocked:'OpenAI blocks cross-site embedding. Details above come from its official API.'});
const states=computed(()=>props.locale.startsWith('zh')?{none:'正常运行',minor:'局部异常',major:'服务异常',critical:'严重故障',maintenance:'维护中',unknown:'状态未获取',investigating:'调查中',identified:'已定位',monitoring:'观察恢复',resolved:'已恢复',degraded_performance:'性能下降',partial_outage:'局部中断',major_outage:'中断',under_maintenance:'维护中'}:{none:'Operational',minor:'Degraded',major:'Disruption',critical:'Major outage',maintenance:'Maintenance',unknown:'Unavailable'});
</script>
<style scoped>
.ai-service-statuses{display:flex;gap:6px;flex-wrap:wrap}.ai-service-status{font:inherit;font-size:11px;color:var(--ai-muted);background:transparent;border:1px solid var(--ai-border);border-radius:5px;display:inline-flex;gap:5px;align-items:center;padding:4px 8px;cursor:pointer}.ai-service-status>span{font-size:8px;color:#37975a}.has-incident>span{color:#c38b24}.is-unknown>span{color:var(--ai-muted)}.ai-status-dialog{width:min(780px,calc(100vw - 24px));max-height:calc(100dvh - 32px);overflow:auto;background:var(--ai-panel);color:var(--ai-text);padding:20px;border:1px solid var(--ai-border);border-radius:10px;scrollbar-width:thin;line-height:1.7}.ai-status-dialog header{display:flex;gap:12px;align-items:center;justify-content:space-between}h2{font-size:17px;margin:0}header button{background:transparent;border:0;color:var(--ai-muted);font:inherit;font-size:24px;cursor:pointer;min-width:32px;min-height:32px}.status-language{display:flex;gap:10px;align-items:center;font-size:11px;color:var(--ai-muted);margin-top:10px}.status-language button{font:inherit;color:var(--ai-action);background:transparent;border:0;cursor:pointer;padding:0}.status-checked,.status-incident>p,time{color:var(--ai-muted);font-size:11px}.status-components{padding:8px 16px;background:var(--ai-hover);font-size:12px}.status-incident{border-top:1px solid var(--ai-border);padding:12px 0}h3{font-size:14px;margin:0}.status-incident>p{margin:2px 0 6px}.status-update p{font-size:13px;margin:0 0 8px;white-space:pre-wrap;overflow-wrap:anywhere}footer{display:flex;gap:8px 16px;flex-wrap:wrap;align-items:center;font-size:12px}footer span{flex-basis:100%;font-size:11px;color:var(--ai-muted)}footer a,footer button{color:var(--ai-action)}footer button{background:var(--ai-hover);border:1px solid var(--ai-border);border-radius:5px;padding:6px 10px;font:inherit;cursor:pointer}iframe{margin-top:12px;width:100%;height:450px;border:1px solid var(--ai-border);background:#fff;border-radius:5px}:is(button,a):focus-visible{outline:2px solid var(--ai-action);outline-offset:2px}@media(max-width:600px){.ai-status-dialog{padding:14px}.ai-service-status{min-height:30px}iframe{height:360px}}
</style>
